const clock = new THREE.Clock();
scene.background = new THREE.Color(0xf8f9fa);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const keyLight = new THREE.DirectionalLight(0xffffff, 1.4);
keyLight.position.set(6, 12, 8);
keyLight.castShadow = true;
keyLight.shadow.mapSize.width = 2048;
keyLight.shadow.mapSize.height = 2048;
keyLight.shadow.camera.near = 0.1;
keyLight.shadow.camera.far = 50;
keyLight.shadow.bias = -0.001;

const fillLight = new THREE.DirectionalLight(0xdbeafe, 0.6);
fillLight.position.set(-8, 6, 4);

const rimLight = new THREE.PointLight(0x60a5fa, 0.5, 25);
rimLight.position.set(-5, 4, -6);

scene.add(new THREE.AmbientLight(0x64748b, 0.35), keyLight, fillLight, rimLight);

const COLORS = {
  curve: 0x3b82f6,
  accent: 0xf59e0b,
  highlight: 0x10b981,
  text: 0x1e293b,
  grid: 0xcbd5e1
};

const gridGroup = new THREE.Group();
const gridHelper = new THREE.GridHelper(20, 20, COLORS.grid, COLORS.grid);
gridHelper.position.y = -2;
gridGroup.add(gridHelper);

const axesGroup = new THREE.Group();
const axisMaterial = new THREE.MeshStandardMaterial({ 
  color: 0x475569, 
  roughness: 0.4, 
  metalness: 0.1 
});

const xAxis = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.03, 12, 16), axisMaterial);
xAxis.rotation.z = -Math.PI / 2;
xAxis.position.y = -2;
axesGroup.add(xAxis);

const yAxis = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.03, 8, 16), axisMaterial);
yAxis.position.set(-6, 0, 0);
axesGroup.add(yAxis);

scene.add(gridGroup);
scene.add(axesGroup);

const curvePath = new THREE.CatmullRomCurve3(
  Array.from({ length: 50 }, (_, i) => {
    const x = -5 + (i / 49) * 10;
    const y = 0.5 * Math.sin(x) + 0.2 * x;
    return new THREE.Vector3(x, y, 0);
  })
);

const tubeGeometry = new THREE.TubeGeometry(curvePath, 64, 0.08, 16, false);
const curveMaterial = new THREE.MeshStandardMaterial({ 
  color: COLORS.curve, 
  roughness: 0.3, 
  metalness: 0.1,
  emissive: COLORS.curve,
  emissiveIntensity: 0.1
});
const curveMesh = new THREE.Mesh(tubeGeometry, curveMaterial);
curveMesh.castShadow = true;
curveMesh.receiveShadow = true;
scene.add(curveMesh);

function getCurvePoint(t) {
  const x = -5 + t * 10;
  const y = 0.5 * Math.sin(x) + 0.2 * x;
  return new THREE.Vector3(x, y, 0);
}

function getDerivative(t) {
  const x = -5 + t * 10;
  return 0.5 * Math.cos(x) + 0.2;
}

const pointGeometry = new THREE.SphereGeometry(0.15, 32, 32);
const fixedPointMaterial = new THREE.MeshStandardMaterial({ 
  color: COLORS.highlight, 
  roughness: 0.2, 
  metalness: 0.3,
  emissive: COLORS.highlight,
  emissiveIntensity: 0.3
});
const movingPointMaterial = new THREE.MeshStandardMaterial({ 
  color: COLORS.accent, 
  roughness: 0.2, 
  metalness: 0.3,
  emissive: COLORS.accent,
  emissiveIntensity: 0.3
});

const fixedPoint = new THREE.Mesh(pointGeometry, fixedPointMaterial);
const movingPoint = new THREE.Mesh(pointGeometry, movingPointMaterial);
fixedPoint.position.copy(getCurvePoint(0.6));
fixedPoint.castShadow = true;
movingPoint.castShadow = true;
scene.add(fixedPoint);
scene.add(movingPoint);

const lineMaterial = new THREE.LineBasicMaterial({ 
  color: COLORS.accent, 
  linewidth: 3,
  opacity: 0.8,
  transparent: true
});

const secantGeometry = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0,0,0), new THREE.Vector3(1,1,0)]);
const secantLine = new THREE.Line(secantGeometry, lineMaterial);
scene.add(secantLine);

const tangentMaterial = new THREE.LineBasicMaterial({ 
  color: COLORS.highlight, 
  linewidth: 4,
  opacity: 0,
  transparent: true
});
const tangentGeometry = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0,0,0), new THREE.Vector3(1,1,0)]);
const tangentLine = new THREE.Line(tangentGeometry, tangentMaterial);
scene.add(tangentLine);

function createLabel(text, color = '#1e293b') {
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');
  canvas.width = 512;
  canvas.height = 256;
  ctx.fillStyle = 'rgba(255,255,255,0)';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.font = 'bold 64px "Times New Roman", serif';
  ctx.fillStyle = color;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, 256, 128);
  const texture = new THREE.CanvasTexture(canvas);
  texture.minFilter = THREE.LinearFilter;
  const material = new THREE.MeshBasicMaterial({ 
    map: texture, 
    transparent: true, 
    side: THREE.DoubleSide,
    opacity: 0
  });
  const geometry = new THREE.PlaneGeometry(3, 1.5);
  const mesh = new THREE.Mesh(geometry, material);
  return mesh;
}

const labelP = createLabel("P", "#10b981");
labelP.position.set(0.5, 0.5, 0);
fixedPoint.add(labelP);

const labelQ = createLabel("Q", "#f59e0b");
labelQ.position.set(0.5, 0.5, 0);
movingPoint.add(labelQ);

const secantLabel = createLabel("Secant", "#f59e0b");
secantLabel.position.set(2, 3, 0);
scene.add(secantLabel);

const tangentLabel = createLabel("Tangent", "#10b981");
tangentLabel.position.set(2, 3.5, 0);
scene.add(tangentLabel);

camera.position.set(0, 2, 8);
camera.lookAt(0, 0, 0);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.target.set(0, 0, 0);

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();
  const cycle = t % 12;

  camera.position.x = Math.sin(t * 0.1) * 0.5;
  camera.lookAt(0, 0, 0);

  if (cycle < 2) {
    const localTime = cycle / 2;
    fixedPoint.scale.setScalar(0);
    movingPoint.scale.setScalar(0);
    secantLine.material.opacity = 0;
    tangentLine.material.opacity = 0;
    secantLabel.material.opacity = 0;
    tangentLabel.material.opacity = 0;
    labelP.material.opacity = 0;
    labelQ.material.opacity = 0;
  } else if (cycle < 3) {
    const localTime = (cycle - 2);
    fixedPoint.scale.setScalar(localTime);
    movingPoint.scale.setScalar(0);
    secantLine.material.opacity = 0;
    tangentLine.material.opacity = 0;
    secantLabel.material.opacity = 0;
    tangentLabel.material.opacity = 0;
    labelP.material.opacity = localTime;
    labelQ.material.opacity = 0;
  } else if (cycle < 7) {
    const localTime = (cycle - 3) / 4;
    fixedPoint.scale.setScalar(1);
    movingPoint.scale.setScalar(1);
    labelP.material.opacity = 1;
    labelQ.material.opacity = 1;

    const startT = 0.9;
    const endT = 0.61;
    const easeT = 1 - Math.pow(1 - localTime, 3);
    const actualT = startT - (startT - endT) * easeT;

    const pPos = getCurvePoint(0.6);
    const qPos = getCurvePoint(actualT);

    fixedPoint.position.copy(pPos);
    movingPoint.position.copy(qPos);

    const positions = new Float32Array([
      pPos.x, pPos.y, pPos.z,
      qPos.x, qPos.y, qPos.z
    ]);
    secantLine.geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    secantLine.geometry.attributes.position.needsUpdate = true;

    secantLine.material.opacity = 0.8;
    tangentLine.material.opacity = 0;
    secantLabel.material.opacity = 1;
    tangentLabel.material.opacity = 0;
    secantLabel.position.set((pPos.x + qPos.x) / 2 + 0.5, (pPos.y + qPos.y) / 2 + 0.8, 0);
  } else if (cycle < 9) {
    const localTime = (cycle - 7) / 2;
    const pPos = getCurvePoint(0.6);
    fixedPoint.position.copy(pPos);
    movingPoint.position.copy(pPos);

    fixedPoint.scale.setScalar(1);
    movingPoint.scale.setScalar(1 - localTime * 0.5);

    secantLine.material.opacity = 0.8 * (1 - localTime);
    secantLabel.material.opacity = 1 - localTime;

    const slope = getDerivative(0.6);
    const length = 3;
    const dx = length / Math.sqrt(1 + slope * slope);
    const dy = slope * dx;

    const tangentPositions = new Float32Array([
      pPos.x - dx, pPos.y - dy, pPos.z,
      pPos.x + dx, pPos.y + dy, pPos.z
    ]);
    tangentLine.geometry.setAttribute('position', new THREE.BufferAttribute(tangentPositions, 3));
    tangentLine.geometry.attributes.position.needsUpdate = true;
    tangentLine.material.opacity = localTime;
    tangentLabel.material.opacity = localTime;
    tangentLabel.position.set(pPos.x + 1.5, pPos.y + slope * 1.5 + 0.5, 0);
  } else {
    const pPos = getCurvePoint(0.6);
    fixedPoint.position.copy(pPos);
    movingPoint.scale.setScalar(0.5);

    const slope = getDerivative(0.6);
    const length = 3;
    const dx = length / Math.sqrt(1 + slope * slope);
    const dy = slope * dx;

    const tangentPositions = new Float32Array([
      pPos.x - dx, pPos.y - dy, pPos.z,
      pPos.x + dx, pPos.y + dy, pPos.z
    ]);
    tangentLine.geometry.setAttribute('position', new THREE.BufferAttribute(tangentPositions, 3));
    tangentLine.geometry.attributes.position.needsUpdate = true;

    tangentLine.material.opacity = 1;
    tangentLabel.material.opacity = 1;
    secantLine.material.opacity = 0;
    secantLabel.material.opacity = 0;
  }

  controls.update();
  renderer.render(scene, camera);
}
animate();

