function updateVideoContent(time) {
  const gradient = ctx.createLinearGradient(0, 0, 1024, 576);
  gradient.addColorStop(0, '#1e3c72');
  gradient.addColorStop(0.5, '#2a5298');
  gradient.addColorStop(1, '#7e8ba3');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, 1024, 576);

  ctx.lineWidth = 4;
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.8)';
  ctx.beginPath();
  for (let i = 0; i < 1024; i += 5) {
    const amplitude = 50 + Math.sin(time * 2 + i * 0.01) * 30;
    const y = 288 + Math.sin(i * 0.02 + time * 3) * amplitude * Math.sin(time + i * 0.005);
    if (i === 0) ctx.moveTo(i, y);
    else ctx.lineTo(i, y);
  }
  ctx.stroke();

  ctx.strokeStyle = 'rgba(100, 200, 255, 0.6)';
  ctx.beginPath();
  for (let i = 0; i < 1024; i += 5) {
    const amplitude = 40 + Math.cos(time * 1.5 + i * 0.02) * 25;
    const y = 288 + Math.cos(i * 0.015 + time * 2.5) * amplitude;
    if (i === 0) ctx.moveTo(i, y);
    else ctx.lineTo(i, y);
  }
  ctx.stroke();

  ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
  ctx.fillRect(100, 500, 824, 12);

  const progress = (time % 10) / 10;
  ctx.fillStyle = '#00d4ff';
  ctx.fillRect(100, 500, 824 * progress, 12);

  const glowGradient = ctx.createLinearGradient(100 + 824 * progress - 20, 500, 100 + 824 * progress + 20, 512);
  glowGradient.addColorStop(0, 'rgba(0, 212, 255, 0)');
  glowGradient.addColorStop(0.5, 'rgba(0, 212, 255, 0.8)');
  glowGradient.addColorStop(1, 'rgba(0, 212, 255, 0)');
  ctx.fillStyle = glowGradient;
  ctx.fillRect(100 + 824 * progress - 20, 498, 40, 16);

  ctx.font = 'bold 48px Arial';
  ctx.fillStyle = 'white';
  ctx.textAlign = 'left';
  ctx.fillText('PLAYING', 100, 100);

  const seconds = Math.floor(time % 60).toString().padStart(2, '0');
  const minutes = Math.floor((time / 60) % 60).toString().padStart(2, '0');
  ctx.font = '36px monospace';
  ctx.fillStyle = 'rgba(255, 255, 255, 0.8)';
  ctx.fillText(`${minutes}:${seconds} / 10:00`, 100, 150);

  const pulse = 1 + Math.sin(time * 4) * 0.1;
  ctx.save();
  ctx.translate(900, 100);
  ctx.scale(pulse, pulse);
  ctx.fillStyle = '#00d4ff';
  ctx.beginPath();
  ctx.moveTo(0, -30);
  ctx.lineTo(40, 0);
  ctx.lineTo(0, 30);
  ctx.closePath();
  ctx.fill();
  ctx.restore();

  ctx.fillStyle = 'rgba(0, 0, 0, 0.1)';
  for (let i = 0; i < 576; i += 4) {
    ctx.fillRect(0, i, 1024, 2);
  }
}

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  updateVideoContent(t);
  videoTexture.needsUpdate = true;

  screenGroup.position.y = 0.5 + Math.sin(t * 0.5) * 0.05;
  screenGroup.rotation.y = Math.sin(t * 0.2) * 0.02;

  screenGlow.intensity = 0.6 + Math.sin(t * 2) * 0.1;
  rimLight.intensity = 0.35 + Math.sin(t * 1.2) * 0.08;

  renderer.render(scene, camera);
}

